// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address origin) public {
        vm.assume(origin != address(0));
        amount = bound(amount, 1 ether, 1000 ether);

        Forwarder f = new Forwarder();
        vm.deal(address(f), amount);

        uint256 before = c.balances(address(f));
        f.deposit(c, amount);
        uint256 afterB = c.balances(address(f));

        assertTrue(afterB == before + amount, "Deposit must credit msg.sender");
    }
}

contract Forwarder {
    function deposit(C c, uint256) external payable {
        c.Deposit{value: msg.value}();
    }
    receive() external payable {}
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function run(uint dep, uint extra) public payable
    {
        require(dep >= 1 ether);
        require(extra > 0 && extra <= 1 ether);
        require(address(this).balance >= dep);

        c.Deposit{value: dep}();
        c.CashOut(dep);
        c.CashOut(extra);

        assert(address(c).balance == 0);
    }

    receive() external payable {}
}

